                    sys_move_cursor(1, print_location_y);
                    sys_screen_scroll(SHELL_BEGIN + 1, SHELL_END - 1);       
                }
                printf("Task(pid=%d) killed\n", pid);
                print_location_y++;
            }
        }
        else if(taskset_command){
            if(strcmp(argv[1], "-p")){
